import{_ as t,o as s,c as o,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Lucid-XR: An Extended-Reality Data Engine for Robotic Manipulation","description":"","frontmatter":{"title":"Lucid-XR: An Extended-Reality Data Engine for Robotic Manipulation","arxiv":"2605.00244","date":"2026-04-30","authors":"Yajvan Ravan, Adam Rashid, Alan Yu, Kai McClennen, Gio Huh, Kevin Yang, Zhutian Yang, Qinxi Yu, Xiaolong Wang, Phillip Isola, Ge Yang","categories":"cs.RO, cs.CV","topics":"物理感知视频生成, 合成数据引擎, 扩展现实遥操作","outline":[2,2]},"headers":[],"relativePath":"papers/2605.00244.md","filePath":"papers/2605.00244.md","lastUpdated":null}'),e={name:"papers/2605.00244.md"};function i(r,a,l,p,u,c){return s(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="lucid-xr-an-extended-reality-data-engine-for-robotic-manipulation" tabindex="-1">Lucid-XR: An Extended-Reality Data Engine for Robotic Manipulation <a class="header-anchor" href="#lucid-xr-an-extended-reality-data-engine-for-robotic-manipulation" aria-label="Permalink to &quot;Lucid-XR: An Extended-Reality Data Engine for Robotic Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.00244" target="_blank" rel="noreferrer">2605.00244</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-04-30</td></tr><tr><td><strong>作者</strong></td><td>Yajvan Ravan, Adam Rashid, Alan Yu, Kai McClennen, Gio Huh, Kevin Yang, Zhutian Yang, Qinxi Yu, Xiaolong Wang, Phillip Isola, Ge Yang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 MuJoCo 编译进浏览器直接跑在 XR 头显上采集低保真虚拟演示，再用语义掩码 + 深度条件的生成式图像管线把它刷成海量真实感训练图，policy 纯合成数据训练即可零样本上真机。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人视觉操作策略的瓶颈不在算法，在数据。真机遥操作采一条轨迹要人工复位物体、挪回夹爪、做安全检查，作者实测在同样的三十分钟里，真机采集只能拿到虚拟环境里大约一半的演示条数。更麻烦的是覆盖度：真实数据集里罕见但关键的场景（杂乱厨房、异常光照、桌布换色）按定义就是稀缺的，而策略恰恰在这些地方崩。Open X-Embodiment 五万条、DROID 十万条这类聚合努力把规模堆上去了，但机器人、环境、任务三个维度的多样性依然远不足以支撑一个&quot;视觉/NLP 基础模型级&quot;的泛化。</p><p>Lucid-XR 想同时解决两件事：让演示采集的<strong>吞吐</strong>摆脱物理世界的复位成本，让演示的<strong>视觉多样性</strong>摆脱三维资产建模的成本。前者靠把物理仿真整个搬进 XR 头显的浏览器里，后者靠一条由文本驱动的生成式图像管线，把少量手工搭的简陋三维场景放大成上百万张不同材质、光照、背景的多视角图像。这件事的价值在于：如果成立，采数据的边际成本从&quot;人 + 机器人 + 场地&quot;降到&quot;人 + 一台三百到四千美元的头显 + 浏览器&quot;，理论上可以互联网规模众包。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VR/AR 遥操作采数据这条线已经很拥挤。DexHub/DART、IRIS、OpenTeach 之类的工具包都能让人在虚拟或增强现实里操控机器人采演示，ARCap、ARMADA、AR2-D2、EVE 则把虚拟机器人叠在真实物体上。作者点出的关键差别是：<strong>这些系统的物理仿真跑在外部主机上</strong>，头显只做渲染和输入，中间隔着 WiFi。对刚体拾放这问题不大，但一旦涉及可变形材料，每帧要同步的是大量网格顶点数据，带宽和延迟直接把交互体验打穿；灵巧、动态的操作（抛球、打结）对延迟尤其敏感。人体到机器人的位姿重定向也是个工程负担——不同运动学结构的机器人各写一套 IK 求解器并部署成服务，扩展性差。</p><p>生成式数据增强这条线，LucidSim 已经证明纯生成图像训练的运动策略能零样本上真机；Gen2Sim、RoboGen 之类能自动造任务但纹理不真实；GenAug、ROSIE、CACTI、DreamGen 则在真实数据上做语义保持的场景幻觉。它们的共同前提是&quot;已经有一批（真实或仿真）演示&quot;。Lucid-XR 的定位是把采集端和增强端接成一条流水线，并且把采集端的成本压到浏览器里。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>倒推一遍：如果延迟来自&quot;物理在别处算、结果传过来&quot;，最直接的消法就是让物理在头显本地算。这一步在几年前不可行，但 WebAssembly 已经能绕开单线程 V8 拿到接近原生的速度，MuJoCo 又恰好是可以整体编译成 wasm 的 C 代码；WebXR 把手部追踪和控制器输入标准化了，WebGL 加上 react-three/fiber 能撑住复杂场景的实时渲染。三个 Web 标准同时成熟，本地物理才成为一个工程选项。</p><p>第二步是重定向。既然 MuJoCo 已经在本地跑，它自带的 IK 求解器就在手边——把 mocap site 焊到指尖和腕关节，用相对位姿驱动，就不需要为每个机器人写代码，只需要在 XML/markup 里声明绑定。这是&quot;复用已有仿真器能力&quot;而非&quot;新造一个算法&quot;的典型思路。</p><p>第三步是视觉。低保真虚拟场景训出的策略在真实相机下必然崩，但 LucidSim 已经给出了答案：用仿真的语义掩码 + 深度做条件控制，让扩散模型只改外观不改几何。把这套东西接在 XR 采集之后，就得到了完整闭环。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>演示数据可以拆成&quot;几何/动作&quot;和&quot;外观&quot;两层：几何和动作必须物理正确，外观只需要足够多样。前者用一个跑在头显本地的轻量物理仿真采集，后者用文本驱动的生成模型批量刷。于是场景可以搭得很简陋（作者明说本文结果只需要&quot;hand-crafted, but basic 3D scenes&quot;），因为外观最终会被生成管线整个覆盖掉，而物理正确性由 MuJoCo 保底。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以论文里的 Kitchen-Sink 任务（拿起杯子、放到碗上、再一起放进水槽）为例走一遍：</p><ul><li><strong>搭场景</strong>：用 <code>vuer-mujoco</code> 的声明式 Python 接口把场景写成组件树（<code>DefaultScene(camera_rig, lighting_rig, table, cup, bowl, ...)</code>），三维资产用 meshy.ai 从文本或商品图生成，再在 MeshLab 里简化面数、重新居中缩放。已有环境可以直接迁移：对 RoboCasa 调 <code>env.get_xml</code>，收集 <code>file=</code> 引用的资产，打包拖进 vuer 即可。</li><li><strong>采演示</strong>：MuJoCo 编译为 WebAssembly 在 Apple Vision Pro 上以 90 fps 实时运行，数据按 25 fps 记录，单步仿真不到 12 ms。默认开启 SDF 碰撞求解器，凹形物体（马克杯、树形晾杯架）不用做凸分解。远处的夹爪用 &quot;hitchhiking controller&quot; 操作：注视并点击激活一个 mocap site，之后以局部坐标系下的 SE(3) 变换驱动，避免手部追踪误差随距离放大。灵巧手则把 mocap site 焊到每根指尖，用相对腕关节的位姿驱动。复位只需按一个按钮，三十分钟可以不间断采集。</li><li><strong>放大数据</strong>：轨迹记录为 SE(3) mocap 位姿，旋转用 6D 表示。相机可以事后在 Python 里改位姿重新回放渲染；有了精确内外参和真值深度，还能计算邻近位姿的光流做图像 warp，降低策略对相机位姿的敏感度。物体和机器人的初始位置用 MimicGen 式的关键点扰动 + 位置线性插值 + 旋转球面插值生成全新演示。</li><li><strong>刷外观</strong>：沿用 LucidSim 配方，用 ChatGPT 元提示批量生成多样文本提示（背景提示尤其复杂），配合仿真给出的语义掩码和归一化逆深度图，在 ComfyUI 工作流里做条件生成，产出多视角真实感图像。</li><li><strong>训策略</strong>：ACT（DETR 式 VAE 骨干）与基于 1D U-Net + FiLM 的扩散策略两条路线，输入本体感受 + 腕部 RGB 或三路固定 RGB，输出分块的绝对末端位姿。</li></ul><p>注意正文 §4.1 与附录表 2 的训练超参不一致（正文写 15k 步、chunk 25、lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>、FFN 256、batch 64；附录写 lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、batch 32、FFN 3200、hidden 512、chunk 10）。两处应指不同实验配置，论文未说明，复现时以附录表为准更稳妥。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：虚拟采集真的更快吗？</strong> 三个任务各在虚拟与真机下采满三十分钟。结论：虚拟环境下参与者拿到的演示条数约为真机遥操作的两倍；再叠加增强管线，有效数据量约为真机基线的五倍。</p><p><strong>问题二：策略能迁到没见过的真实场景吗？</strong> 作者用 PolyCam 扫了几个带真实杂物的厨房，做成 3D Gaussian 场景并与 MuJoCo 碰撞几何手工对齐，作为&quot;real-to-sim&quot;评测台。Kitchen Clearing 任务上（每次运行两次拾放、四分制）：纯 ACT 在基础环境 100%，一进低杂乱环境掉到 0%，高杂乱 + 噪声也是 0%；ACT + LucidSim 则是 100% / 90% / 25%。这是全文最锋利的一组数字——生成式增强不是锦上添花，而是决定策略在有杂物的场景里是否存在。</p><p><strong>问题三：合成数据能替代真机数据吗？</strong> 用 10/20/30 分钟三档数据分别训练 LucidXR 策略与真机遥操作（Oculus 控制末端）策略，在真机上、在真实数据采集的<strong>同一环境</strong>里评测：两者表现相当。随后改变光照、颜色，把木质桌面换成花纹桌布或黑色桌布：只用真机演示训的策略泛化失败，LucidXR 策略维持高成功率并反超。</p><p>需要如实指出：问题三的结果只以柱状图（图 11）呈现，正文未给出具体数值；问题一的倍数（约 2× 与约 5×）同样只有图和&quot;roughly / about&quot;的措辞。此外，附录里还观察到策略学出了重试行为（马克杯挂架任务里两次接触后重新尝试），但这是定性观察，无统计。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：Lucid-XR 把 MuJoCo 编译成 WebAssembly 直接跑在 XR 头显浏览器里，物理与渲染都在设备本地，消除了网络延迟，从而支持可变形材料、颗粒流体、SDF 凹面碰撞等接触密集场景的实时交互采集。人到机器人的重定向不再需要写代码或部署服务器，只需在 markup 里把 mocap site 绑到指尖与腕部。采到的低保真演示经过轨迹扰动、相机重投影和 LucidSim 式的语义掩码 + 深度条件生成，被放大成多样真实感图像。同等采集时长下虚拟环境产出约两倍演示，叠加增强后有效数据约五倍。纯合成数据训练的策略在真机上与真机数据训练的策略相当，且在改变光照与桌面材质后显著更鲁棒。</p><p><strong>3 句话版</strong>：把物理仿真搬进头显浏览器，让众包采集摆脱延迟与复位成本；用生成式图像管线把简陋场景刷成海量真实感数据，让外观多样性摆脱建模成本；两者串起来，纯合成数据训出的操作策略可以零样本上真机并抗视觉扰动。</p><p><strong>1 句话版</strong>：几何靠本地物理仿真保证正确，外观靠生成模型保证多样，机器人操作数据因此可以在浏览器里规模化生产。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>低保真物理仿真里采到的人类演示动作，在真实世界的接触动力学下依然是可执行的最优或近优动作</strong>。整套系统只对&quot;外观&quot;做了 sim-to-real 修补，对&quot;物理&quot;没有任何修补——没有域随机化接触参数，没有真实力/触觉数据回灌，没有系统辨识。MuJoCo 的柔体、颗粒、粘附（论文用 adhesion actuator 模拟磁性钩子钓鱼玩具）本质是可调参的近似模型，作者自己就说钓鱼玩具的鱼重需要手工调到&quot;能吊起来但轻抖会脱落&quot;。一旦任务成功与否由亚毫米级的接触细节决定（附录明确列出的 tight insertion 紧公差插入、打结、马克杯挂架），演示里的动作在真机上可能根本不可行，而这类失败无法靠换外观修好。</p><p>论文为此提供的证据是间接的：拾放任务的 sim-to-real 迁移成功。但拾放恰恰是对接触细节最不敏感的一类任务。那些真正考验接触物理的任务（图 8 列出的五个）只在仿真里评测，没有对应的真机数字。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要复现整套 XR 栈的验证：</p><ol><li>在桌面 MuJoCo 里搭一个最简单的拾放场景，用脚本策略（而非人类演示）生成 200 条轨迹，同时导出 RGB、语义掩码、深度。</li><li>用任意开源 ControlNet（掩码 + 深度双条件）+ 一批 ChatGPT 生成的背景/材质提示，把每条轨迹刷成 5 种外观，得到 1000 条视觉多样的演示。</li><li>训三个 ACT 策略：仅原始仿真渲染、仅生成图像、两者混合。</li><li>在<strong>改变了纹理与光照</strong>的仿真环境里评测（这正好复刻论文的 real-to-sim 台架，但不需要三维扫描）。</li></ol><p>支持论文的结果：生成图像组在改动环境上的成功率显著高于原始渲染组，且原始渲染组接近 0（对应表 1 的 100% → 0%）。反驳的结果：两组差距在十几个百分点以内，说明杂乱场景下的崩塌主要由几何/杂物遮挡而非外观分布差异造成。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>表 1 是全文最有说服力的证据，但它同时是最好的攻击点。ACT 基线在低杂乱环境从 100% 直接掉到 0%，这个断崖太干净了，不像是&quot;外观分布偏移导致性能退化&quot;，更像是&quot;策略在训练分布外直接进入未定义行为&quot;。一个替代解释是：基线 ACT 训练数据里几乎不含任何干扰物，所以模型学到的是&quot;整幅图里唯一的物体就是目标&quot;，加入杂物后注意力被完全劫持；而 LucidSim 增强的背景提示天然引入了大量无关物体（附录提示词里就有&quot;chaotic ensemble of baking supplies... flour dusts the edges&quot;），于是增强的真正作用是<strong>引入了干扰物</strong>，而不是&quot;提升了真实感&quot;。</p><p>对应的判别实验：把生成管线的提示词固定为&quot;干净纯色背景&quot;，只随机化目标物体的材质与光照，保持背景无杂物。如果这版增强在低杂乱环境上仍能拿到接近 90%，论文的&quot;真实感/多样性&quot;叙事成立；如果掉回接近基线，那么应该把结论改写为&quot;训练时必须见过干扰物&quot;，这是一个便宜得多、也更容易执行的处方，且不依赖生成模型。</p><p>第二个可预测的失败场景：论文自己在 Limitations 里承认依赖&quot;同一段文本提示生成一致的多视角图像&quot;。当同一时刻的三路固定相机各自独立生成时，多视角之间的外观一致性没有任何约束。对需要跨视角三角化的任务（精确插入、双手交接），这种视角间的外观漂移会系统性地破坏几何线索——而论文评测的多视角任务恰好都是仿真内评测。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限</strong>：Lucid-XR 把&quot;外观&quot;交给生成模型、把&quot;物理&quot;交给 MuJoCo，两者之间是单向的（物理 → 掩码 → 图像）。生成模型永远不知道自己刷出来的材质在物理上意味着什么：它可以把一个 MuJoCo 里设定为刚体的杯子渲染成一只软塑料杯，而动作数据仍然按刚体记录。这条视觉-物理的语义裂缝是纯外观增强的天花板。</p><p><strong>新 framing</strong>：把提示词从&quot;外观描述&quot;升级为&quot;材质本体描述&quot;，让同一条文本同时驱动图像生成<strong>和</strong> MuJoCo 的物理参数（质量、摩擦、杨氏模量、粘附强度、颗粒尺寸）。相邻领域可以借的工具是可微仿真与系统辨识里的参数推断：给定一小批真实视频，反解出&quot;文本 → 物理参数&quot;的映射，再把这个映射用作生成端的联合条件。这样域随机化就不再是外观层的噪声注入，而是<strong>物理与外观联合采样的一致分布</strong>。</p><p><strong>第一个实验</strong>：取三种材质差异明显的物体（金属杯、纸杯、硅胶杯），在 Lucid-XR 里各采 30 条倒水/挤压演示，让文本同时指定外观与物理参数。训练两个策略：一个用外观随机化 + 固定物理，一个用联合随机化。在真机上评测&quot;根据视觉外观选择合适抓握力&quot;的任务。若联合随机化的策略能在没见过的材质上正确调整抓握（例如对纸杯减力），说明生成模型的语义确实可以承载物理先验，而不只是贴图。</p>',45)])])}const g=t(e,[["render",i]]);export{h as __pageData,g as default};
